import math

def bounds(call_put, S, K, r, T):
    discounted_K = K * math.exp(-r * T)
    if call_put == 'call':
        lower = max(0.0, S - discounted_K)
        upper = S
    elif call_put == 'put':
        lower = max(0.0, discounted_K - S)
        upper = discounted_K
    else:
        raise ValueError('call_put must be "call" or "put"')
    return (lower, upper)

