def max_area(height):
    left, right = 0, len(height) - 1
    max_area = 0
    while left < right:
        width = right - left
        cur_area = width * min(height[left], height[right])
        max_area = max(max_area, cur_area)
        if height[left] < height[right]:
            left += 1
        else:
            right -= 1
    return max_area

