def kahn_topological_sort(num_vertices, edges):
    from collections import deque, defaultdict
    indegree = [0]*num_vertices
    graph = defaultdict(list)
    for u,v in edges:
        graph[u].append(v)
        indegree[v] += 1
    q = deque([i for i in range(num_vertices) if indegree[i]==0])
    order = []
    while q:
        u = q.popleft()
        order.append(u)
        for v in graph[u]:
            indegree[v] -= 1
            if indegree[v]==0:
                q.append(v)
    if len(order)!=num_vertices:
        raise ValueError('Graph has a cycle')
    return order

