import heapq

def dijkstra(num_vertices, adjacency_list, source):
    dist = [float('inf')]*num_vertices
    dist[source] = 0
    heap = [(0, source)]
    while heap:
        d,u = heapq.heappop(heap)
        if d!=dist[u]:
            continue
        for v,w in adjacency_list.get(u, []):
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    return dist

import heapq

def top_k(nums, k):
    if k <= 0:
        return []
    # Initialize min‑heap with first k elements
    heap = nums[:k]
    heapq.heapify(heap)
    for num in nums[k:]:
        if num > heap[0]:
            heapq.heapreplace(heap, num)
    # Return elements sorted descending for readability
    return sorted(heap, reverse=True)

